        throw std::runtime_error("Caracter no admitido");
    }
    if (entrada.bad() || !entrada.eof()) {
        throw std::runtime_error("Fallo del flujo");
    }
    return Token{'f', 0};
}

bool token_valido(Token token) {
    if (token.clase == 'n') {
        return token.valor >= 0 && token.valor <= 99;
    }
    const bool signo = token.clase == '+' || token.clase == '-'
        || token.clase == '*' || token.clase == '/'
        || token.clase == '(' || token.clase == ')' || token.clase == ';';
    return token.valor == 0 && (signo || token.clase == 'f');
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {}

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(Token token) {
        if (lleno_) {
            throw std::runtime_error("Buffer ocupado");
        }
        if (!token_valido(token)) {
            throw std::runtime_error("Token invalido");
        }
        guardado_ = token;
        lleno_ = true;
    }

    bool tiene_pendiente() const {
        return lleno_;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{'f', 0};
};

void trazar(const std::string& texto) {
    Lector_tokens lector{texto};
    try {
        const Token primero = lector.leer();
        std::cout << "Numero: " << primero.valor << "\n";
        lector.devolver(primero);
        const Token repetido = lector.leer();
        std::cout << "Repetido: " << repetido.valor << "\n";
        const Token signo = lector.leer();
        std::cout << "Signo: " << signo.clase << "\n";
        const Token siguiente = lector.leer();
        std::cout << "Siguiente: " << siguiente.valor;
    } catch (const std::runtime_error& error) {
        std::cout << "Error: " << error.what();
    }
    std::cout << "\n";
}

int main() {
    trazar("34+5;");
    trazar("99+0;");
    trazar("007+2;");
    trazar("100+1;");
    Lector_tokens final{"99"};
    std::cout << "Numero final: " << final.leer().valor << "\n";
    std::cout << "Fin: " << final.leer().clase << "\n";
    Lector_tokens separados{"1 2"};
    const Token primero = separados.leer();
    const Token segundo = separados.leer();
    std::cout << "Separados: " << primero.valor << ":" << segundo.valor << "\n";
    return 0;
}
